"""Render the human-voice pronunciation collection from reviewed source records."""
import json, html
from mind_atlas import render as render_atlas
from pathlib import Path
E=html.escape

def render(root):
    words=json.loads((root/'mind-words.json').read_text())
    n=len(words)
    rows=''
    credits=''
    for w in words:
        context=f'<p class="recording-context">Recorded phrase: {E(w["recordedText"])}</p>' if w.get('recordingContext')=='phrase' else ''
        extra=f' · <a href="{E(w["additionalSource"])}">Additional lexical source</a>' if w.get('additionalSource') else ''
        rows+=f'''<article class="spoken-row" data-id="{w['id']}"><button type="button" aria-label="Hear {E(w['language'])}: {E(w['word'])}"><span lang="{w['code']}" dir="{w.get('direction','auto')}">{E(w['word'])}</span></button><h3>{E(w['language'])}</h3><p>{E(w['roman'])}</p><p>{E(w['meaning'])}</p>{context}<noscript><audio controls preload="none" src="{w['audio']}"></audio></noscript></article>'''
        credits+=f'''<li id="credit-{w['id']}"><strong>{E(w['language'])} · <span lang="{w['code']}">{E(w['word'])}</span></strong><br>{E(w['credit'])}. <a href="{E(w['source'])}">Original recording and attribution</a> · <a href="{E(w['licenseUrl'])}">{E(w['license'])}</a> · <a href="{E(w['dictionary'])}">Word source</a>{extra}. Converted to MP3; pronunciation unaltered.</li>'''
    first=next(w for w in words if w['id']=='en')
    return f'''<link rel="stylesheet" href="mind-words.css"><link rel="stylesheet" href="mind-atlas.css"><script src="mind-atlas.js" defer></script><script src="mind-words.js" defer></script>
<div class="spoken-heading"><h1>MIND, in {n} languages.</h1><p>Select a word to hear a person say it. Every entry uses a human recording. Romanian and Hausa preserve short phrases containing the word; both are labeled.</p></div>
<nav class="atlas-nav" aria-label="Explore mind"><a href="#meanings">Meaning clusters</a><a href="#spoken-controls">Listen</a><a href="#signs">Sign languages</a><a href="#symbols">Art &amp; symbols</a><a href="#all-words">All 50 words</a></nav>
<section id="spoken-controls" hidden aria-label="Listen to words for mind"><div class="spoken-stage"><figure class="spoken-figure"><svg id="spoken-wheel" viewBox="0 0 1000 1000" role="group" aria-label="Words for mind. Select a word to hear it."></svg><figcaption class="spoken-center"><div><span class="center-label">{n} languages · Human voices</span><h2 id="current-word" lang="{first['code']}">{E(first['word'])}</h2><p id="current-language">{E(first['language'])}</p><button id="center-replay" type="button" aria-label="Hear selected word"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 5 19 12 9 19Z"/></svg>Listen</button></div></figcaption></figure><div class="spoken-player"><div class="spoken-actions"><button id="replay" type="button">Hear this word</button><button id="play-all" type="button" aria-pressed="false">Play all</button><button id="stop-audio" type="button" disabled>Stop</button></div><p id="spoken-status" role="status" aria-live="polite">Select a word, or play the collection.</p><h2 class="player-heading">The word &amp; its meaning</h2><p id="current-roman"></p><p id="current-meaning"></p><p id="current-note"></p><p id="current-type">Speaker recording</p><div class="spoken-links"><a id="current-source" href="{E(first['dictionary'])}">Word source</a><a id="current-credit" href="#credit-{first['id']}">Recording credit</a></div></div></div></section>{render_atlas(root)}<section id="all-words"><div class="spoken-search"><label for="word-search">Find a language or word<input id="word-search" type="search" placeholder="Korean, heart, 마음…" autocomplete="off"></label><p id="word-count" role="status">{n} languages</p></div></section>
<div class="spoken-list">{rows}</div>
<section class="spoken-notes"><h2>One English word, several kinds of meaning.</h2><p>These words have senses that overlap with mind, heart, thought, spirit or understanding. Each entry names a relevant sense; it does not make the words exact equivalents. A dictionary gloss cannot stand for a whole culture or philosophical tradition.</p><p>Recordings preserve individual voices and accents. Romanizations help identify words; they are not English pronunciation guides. Selection checks pair the recording’s documented language and word with its dictionary entry. The collection has not received native-speaker review in every language. French and Swedish include an article. Romanian and Hausa preserve a short phrase containing the selected word, with the phrase shown before playback.</p><p><a href="syllabus.html#language">Read the syllabus’s language comparison</a> · <a href="https://omatty123.github.io/h2o/">Visit the WATER project</a></p></section>
<section class="spoken-credits"><h2>Recording credits &amp; word sources</h2><p>Human recordings from Wikimedia Commons and Lingua Libre. The original file page supplies each recording’s attribution and reuse terms. Brief meanings refer to the linked dictionaries, principally Wiktionary; <a href="https://creativecommons.org/licenses/by-sa/4.0/">Wiktionary text license</a>. Sources checked 10 October 2026.</p><ol>{credits}</ol><p><a href="mind-words.json" download>Download the source records (JSON)</a></p></section>
<script id="spoken-data" type="application/json">{json.dumps(words,ensure_ascii=False).replace('<',chr(92)+'u003c')}</script>'''
